#!/usr/bin/env bash

# Generated by lambda2eks. Moves a Route 53 name from the API Gateway custom domain (Lambda)
# to the ALB (EKS) in weighted steps. Every change is one atomic change batch.

DEPENDENCIES=(aws jq kubectl)
SCRIPT_NAME=$(basename "$0")
STATE_DIR="$(cd "$(dirname "$0")" && pwd)/.state"
NAMESPACE="${NAMESPACE:-__NAMESPACE__}"
INGRESS="${INGRESS:-__INGRESS__}"

RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
NC='\033[0m'
if [[ -n "${NO_COLOR:-}" ]] || [[ "${TERM:-}" == "dumb" ]] || [[ ! -t 1 ]]; then
    RED="" GREEN="" YELLOW="" NC=""
fi

function usage() {
    cat <<EOM

Shift traffic for one DNS name from the Lambda (API Gateway custom domain) to EKS (the ALB).

usage: ${SCRIPT_NAME} <command>

commands:
    status        Show the current records for the name
    init          Replace the simple alias record with two weighted ones: lambda=100, eks=0
    set <0-100>   Send this percentage of new DNS lookups to EKS
    finish        Replace the weighted pair with one simple alias to the ALB
    rollback      Restore the record exactly as it was before init

environment:
    HOSTED_ZONE_ID   Route 53 hosted zone id (required)
    RECORD_NAME      DNS name clients use, e.g. api.example.com (required)
    ALB_DNS          ALB hostname (default: read from ingress ${INGRESS} in ${NAMESPACE})
    ALB_ZONE         ALB canonical hosted zone id (default: looked up from ALB_DNS)

dependencies: ${DEPENDENCIES[*]}

examples:
    HOSTED_ZONE_ID=Z123 RECORD_NAME=api.example.com ${SCRIPT_NAME} init
    HOSTED_ZONE_ID=Z123 RECORD_NAME=api.example.com ${SCRIPT_NAME} set 10

EOM
    exit 1
}

function main() {
    local command="${1:-}"
    local weight="${2:-}"

    case "$command" in
    status | init | finish | rollback) ;;
    set)
        if ! [[ "$weight" =~ ^[0-9]+$ ]] || ((weight > 100)); then
            print_error "set needs a percentage from 0 to 100"
            usage
        fi
        ;;
    -h | --help | "") usage ;;
    *)
        print_error "unknown command '$command'"
        usage
        ;;
    esac

    exit_on_missing_tools "${DEPENDENCIES[@]}"
    if [[ -z "${HOSTED_ZONE_ID:-}" ]] || [[ -z "${RECORD_NAME:-}" ]]; then
        print_error "set HOSTED_ZONE_ID and RECORD_NAME"
        usage
    fi
    FQDN="${RECORD_NAME%.}."

    case "$command" in
    status) show_records ;;
    init) init_weighted ;;
    set) set_weight "$weight" ;;
    finish) finish_on_eks ;;
    rollback) rollback_to_original ;;
    esac
}

function records() {
    local all
    all=$(aws route53 list-resource-record-sets --hosted-zone-id "$HOSTED_ZONE_ID" --output json) || {
        print_error "could not list the records of zone ${HOSTED_ZONE_ID}"
        return 1
    }
    echo "$all" | jq --arg name "$FQDN" '[.ResourceRecordSets[] | select(.Name == $name and (.Type == "A" or .Type == "AAAA"))]'
}

function show_records() {
    local current
    current=$(records) || exit 1
    echo "$current" | jq -r '.[] | "\(.Type) \(.SetIdentifier // "simple") weight=\(.Weight // "-") -> \(.AliasTarget.DNSName // .ResourceRecords)"'
}

function alb_target() {
    local dns="${ALB_DNS:-}"
    local zone="${ALB_ZONE:-}"
    if [[ -z "$dns" ]]; then
        dns=$(kubectl -n "$NAMESPACE" get ingress "$INGRESS" -o jsonpath='{.status.loadBalancer.ingress[0].hostname}')
        if [[ -z "$dns" ]]; then
            print_error "ingress ${INGRESS} has no load balancer yet; set ALB_DNS"
            exit 1
        fi
    fi
    if [[ -z "$zone" ]]; then
        zone=$(aws elbv2 describe-load-balancers --output text \
            --query "LoadBalancers[?DNSName=='${dns}'].CanonicalHostedZoneId | [0]")
        if [[ -z "$zone" ]] || [[ "$zone" == "None" ]]; then
            print_error "could not find the hosted zone of ${dns}; set ALB_ZONE"
            exit 1
        fi
    fi
    jq -n --arg dns "$dns" --arg zone "$zone" '{HostedZoneId: $zone, DNSName: $dns, EvaluateTargetHealth: true}'
}

function apply_changes() {
    local batch="$1"
    local change_id
    echo "$batch" | jq .
    change_id=$(aws route53 change-resource-record-sets --hosted-zone-id "$HOSTED_ZONE_ID" \
        --change-batch "$batch" --query ChangeInfo.Id --output text) || {
        print_error "Route 53 rejected the change; nothing was modified"
        exit 1
    }
    if ! aws route53 wait resource-record-sets-changed --id "$change_id"; then
        print_error "change ${change_id} did not reach INSYNC; check it before going on"
        exit 1
    fi
    print_success "change ${change_id} is in sync"
}

function init_weighted() {
    local current alb
    current=$(records) || exit 1
    if [[ $(echo "$current" | jq 'map(select(.Type == "AAAA")) | length') -gt 0 ]]; then
        print_error "${FQDN} has an AAAA record; this script handles A only, move AAAA by hand"
        exit 1
    fi
    if [[ $(echo "$current" | jq 'length') -ne 1 ]] || [[ $(echo "$current" | jq '.[0] | has("SetIdentifier")') == "true" ]]; then
        print_error "expected exactly one simple A record for ${FQDN}; run status"
        exit 1
    fi
    alb=$(alb_target) || exit 1
    mkdir -p "$STATE_DIR"
    echo "$current" | jq '.[0]' >"${STATE_DIR}/route53-original.json"
    apply_changes "$(echo "$current" | jq --argjson alb "$alb" '{Changes: [
        {Action: "DELETE", ResourceRecordSet: .[0]},
        {Action: "CREATE", ResourceRecordSet: (.[0] + {SetIdentifier: "lambda", Weight: 100})},
        {Action: "CREATE", ResourceRecordSet: {Name: .[0].Name, Type: "A", SetIdentifier: "eks", Weight: 0, AliasTarget: $alb}}
    ]}')"
}

function set_weight() {
    local eks="$1"
    local current
    current=$(records) || exit 1
    if [[ $(echo "$current" | jq 'map(select(.SetIdentifier == "lambda" or .SetIdentifier == "eks")) | length') -ne 2 ]]; then
        print_error "the weighted lambda/eks records are not there; run init first"
        exit 1
    fi
    apply_changes "$(echo "$current" | jq --argjson eks "$eks" '{Changes: [.[] |
        select(.SetIdentifier == "lambda" or .SetIdentifier == "eks") |
        {Action: "UPSERT", ResourceRecordSet: (. + {Weight: (if .SetIdentifier == "eks" then $eks else 100 - $eks end)})}]}')"
    print_warning "clients and resolvers cache answers for the alias TTL; give each step a few minutes before judging it"
}

function finish_on_eks() {
    local current
    current=$(records) || exit 1
    if [[ $(echo "$current" | jq 'map(select(.SetIdentifier == "eks" and .Weight == 100)) | length') -ne 1 ]]; then
        print_error "EKS is not at 100%; run 'set 100' and let it settle first"
        exit 1
    fi
    apply_changes "$(echo "$current" | jq '{Changes: (
        [.[] | select(.SetIdentifier == "lambda" or .SetIdentifier == "eks") | {Action: "DELETE", ResourceRecordSet: .}] +
        [{Action: "CREATE", ResourceRecordSet: (.[] | select(.SetIdentifier == "eks") | del(.SetIdentifier, .Weight))}])}')"
}

function rollback_to_original() {
    local current original="${STATE_DIR}/route53-original.json"
    if [[ ! -f "$original" ]]; then
        print_error "no saved record at ${original}; use 'set 0' to send everything back to the Lambda"
        exit 1
    fi
    current=$(records) || exit 1
    apply_changes "$(echo "$current" | jq --slurpfile orig "$original" '{Changes: (
        [.[] | select(.Type == "A") | {Action: "DELETE", ResourceRecordSet: .}] +
        [{Action: "CREATE", ResourceRecordSet: $orig[0]}])}')"
}

function print_success() {
    echo -e "${GREEN}OK: $1${NC}"
}

function print_warning() {
    echo -e "${YELLOW}Warning: $1${NC}"
}

function print_error() {
    echo -e "${RED}Error: $1${NC}" >&2
}

function exit_on_missing_tools() {
    for cmd in "$@"; do
        if command -v "$cmd" &>/dev/null; then
            continue
        fi
        print_error "required tool '${cmd}' is not installed or not in PATH"
        exit 1
    done
}

if [[ "${BASH_SOURCE[0]}" == "${0}" ]]; then
    main "$@"
    exit 0
fi
